def count_cyclical_neighbors(grid, row, col):
    """Count all 8 neighbors (orthogonal + diagonal)"""
    h, w = len(grid), len(grid[0])
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = row + dr, col + dc
            if 0 <= nr < h and 0 <= nc < w:
                neighbors.append((nr, nc, grid[nr][nc]))
    return neighbors

