def identify_4connected_components(grid):
    """Find 4-connected components of cells with value 8"""
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    for row in range(h):
        for col in range(w):
            if grid[row][col] == 8 and not visited[row][col]:
                component = []
                stack = [(row, col)]
                while stack:
                    r, c = stack.pop()
                    if visited[r][c]:
                        continue
                    visited[r][c] = True
                    component.append((r, c))
                    # 4 neighbors
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 8 and not visited[nr][nc]:
                            stack.append((nr, nc))
                components.append(component)

    return components

