def distance_to_0_nearest_dir(grid, row, col, direction):
    """Find minimum distance to a 0 in a given direction (have/dont go back over 8s)"""
    h, w = len(grid), len(grid[0])
    directions = {
        'T': (-1, 0),   # top
        'B': (1, 0),    # bottom
        'L': (0, -1),   # left
        'R': (0, 1)     # right
    }
    dr, dc = directions[direction]
    dist = 0
    while True:
        nr, nc = row + dr * dist, col + dc * dist
        if not (0 <= nr < h and 0 <= nc < w):
            return float('inf')  # blocked by grid boundary
        if grid[nr][nc] == 0:
            return dist
        if grid[nr][nc] == 8 and dist > 0:
            return float('inf')  # blocked by other 8s past this
        dist += 1

