def nearest_0_direction(grid, row, col):
    """Find the direction (T/B/L/R) to the nearest 0"""
    h, w = len(grid), len(grid[0])
    dirs = {'T': (-1, 0), 'B': (1, 0), 'L': (0, -1), 'R': (0, 1)}
    best_dir = None
    best_dist = float('inf')

    for dname, (dr, dc) in dirs.items():
        dist = 0
        while True:
            nr, nc = row + dr * dist, col + dc * dist
            if not (0 <= nr < h and 0 <= nc < w):
                break
            if grid[nr][nc] == 0:
                if dist < best_dist:
                    best_dist = dist
                    best_dir = dname
                break
            if grid[nr][nc] == 8 and dist > 0:
                break
            dist += 1

    return best_dir, best_dist

